function isoDate(value: Date) { return value.toISOString().slice(0, 10); }
function activeLocale() { return typeof document !== "undefined" && document.documentElement.lang.startsWith("en") ? "en-GB" : "pt-PT"; }
function number(value: unknown, digits = 2) { const parsed = Number(value); return Number.isFinite(parsed) ? new Intl.NumberFormat(activeLocale(), { maximumFractionDigits: digits, minimumFractionDigits: 0 }).format(parsed) : "—"; }
function valueOf(latest: Record<string, any> | undefined, code: string) { return latest?.[code]?.dataQuality === "invalid" ? null : latest?.[code]?.value ?? null; }
function readFile(file: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result || "").split(",")[1]; base64 ? resolve(base64) : reject(new Error("Não foi possível ler o ficheiro.")); }; reader.onerror = () => reject(new Error("Não foi possível ler o ficheiro.")); reader.readAsDataURL(file); }); }

